pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    assert!(!sep.is_empty(), "separator must be non-empty");

    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                return vec![s];
            }

            if s.is_empty() {
                return vec![String::new()];
            }

            // rsplitn takes "number of pieces", which is maxsplit + 1.
            // It yields pieces from right to left, so reverse to match left-to-right order.
            let mut parts: Vec<String> = s
                .rsplitn((maxsplit as usize) + 1, &sep)
                .map(|p| p.to_string())
                .collect();

            parts.reverse();

            // Ensure inner list is non-empty (should always hold given rsplitn behavior).
            if parts.is_empty() {
                vec![s]
            } else {
                parts
            }
        })
        .collect()
}